import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, Eye, EyeOff } from 'lucide-react';
import { BtnOrange, TextInput, C } from '../components/UI';
import { useApp } from '../context/AppContext';

export default function SignInScreen() {
  const navigate = useNavigate();
  const { setUser } = useApp();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');

  function handleSignIn() {
    if (!email || !password) { setError('Please fill in all fields.'); return; }
    // MVP: accept any credentials
    setUser({ name: 'Arjun', email, avatar: null });
    navigate('/home');
  }

  return (
    <div style={{
      minHeight: '100vh', maxWidth: 430, margin: '0 auto',
      background: '#111', padding: '0 24px',
      display: 'flex', flexDirection: 'column',
    }}>
      <button onClick={() => navigate(-1)} style={{ background: 'none', border: 'none', color: '#fff', cursor: 'pointer', padding: '20px 0 0', fontSize: 20, alignSelf: 'flex-start' }}>←</button>

      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', paddingBottom: 40 }}>
        <h1 style={{ fontSize: 30, fontWeight: 800, color: '#fff', marginBottom: 6 }}>
          Welcome Back! 👋
        </h1>
        <p style={{ color: '#777', fontSize: 14, marginBottom: 36 }}>Sign in to continue</p>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <TextInput
            icon={Mail}
            placeholder="Email"
            value={email}
            onChange={e => setEmail(e.target.value)}
            type="email"
          />
          <TextInput
            icon={Lock}
            placeholder="Password"
            value={password}
            onChange={e => setPassword(e.target.value)}
            type={showPass ? 'text' : 'password'}
            rightIcon={
              <button onClick={() => setShowPass(v => !v)} style={{ background: 'none', border: 'none', color: '#666', cursor: 'pointer', padding: 0 }}>
                {showPass ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            }
          />
        </div>

        {error && <p style={{ color: '#ff4d6d', fontSize: 12, marginTop: 8 }}>{error}</p>}

        <button
          onClick={() => {}}
          style={{ background: 'none', border: 'none', color: C.orange, fontSize: 13, fontWeight: 600, cursor: 'pointer', textAlign: 'right', marginTop: 10, marginBottom: 24 }}
        >
          Forgot Password?
        </button>

        <BtnOrange onClick={handleSignIn}>Sign In</BtnOrange>

        <div style={{ display: 'flex', alignItems: 'center', gap: 12, margin: '20px 0' }}>
          <div style={{ flex: 1, height: 1, background: '#2a2a2a' }} />
          <span style={{ color: '#555', fontSize: 12 }}>or continue with</span>
          <div style={{ flex: 1, height: 1, background: '#2a2a2a' }} />
        </div>

        <button
          onClick={() => { setUser({ name: 'Arjun', email: 'arjun.sharma@email.com', avatar: null }); navigate('/home'); }}
          style={{
            width: '100%', padding: '13px', borderRadius: 12,
            background: '#1e1e1e', border: '1px solid #2e2e2e',
            color: '#fff', fontSize: 14, fontWeight: 600, cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
          }}
        >
          <span style={{ fontSize: 18 }}>G</span> Continue with Google
        </button>

        <p style={{ textAlign: 'center', color: '#666', fontSize: 13, marginTop: 24 }}>
          Don't have an account?{' '}
          <span onClick={() => navigate('/signup')} style={{ color: C.orange, fontWeight: 700, cursor: 'pointer' }}>
            Sign Up
          </span>
        </p>
      </div>
    </div>
  );
}
